def counting_sort(a, k):
    count = [0] * (k + 1)
    output = [None] * len(a)
    for x in a:
        count[x] += 1
    for v in range(1, k + 1):
        count[v] += count[v - 1]
    for j in reversed(range(len(a))):
        x = a[j]
        output[count[x] - 1] = x
        count[x] -= 1
    return output

